"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[387],{1860(e,o,t){t.r(o),t.d(o,{assets:()=>s,contentTitle:()=>l,default:()=>h,frontMatter:()=>r,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"leave","title":"IV. LEAVE OF ABSENCE POLICIES","description":"FAMILY AND MEDICAL LEAVE","source":"@site/docs/04-leave.md","sourceDirName":".","slug":"/leave","permalink":"/pps-erp-sdd/leave","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/04-leave.md","tags":[],"version":"current","sidebarPosition":4,"frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"III. COMPENSATION POLICY","permalink":"/pps-erp-sdd/compensation"},"next":{"title":"V. GROUP AND HEALTH RELATED BENEFITS","permalink":"/pps-erp-sdd/health"}}');var i=t(4848),a=t(8453);const r={},l="IV. LEAVE OF ABSENCE POLICIES",s={},d=[{value:"FAMILY AND MEDICAL LEAVE",id:"family-and-medical-leave",level:2},{value:"Eligible Employee",id:"eligible-employee",level:3},{value:"Length of Leave",id:"length-of-leave",level:4},{value:"Substitution of Paid Leave",id:"substitution-of-paid-leave",level:3},{value:"Employee Notification Requirements",id:"employee-notification-requirements",level:4},{value:"Medical Certification",id:"medical-certification",level:4},{value:"Benefits Continuation",id:"benefits-continuation",level:4},{value:"Job Restoration",id:"job-restoration",level:4},{value:"Workers&#39; Compensation and Family and Medical Leave",id:"workers-compensation-and-family-and-medical-leave",level:4},{value:"Questions About Family and Medical Leave",id:"questions-about-family-and-medical-leave",level:4},{value:"PREGNANCY DISABILITY LEAVE",id:"pregnancy-disability-leave",level:2},{value:"MILITARY LEAVE OF ABSENCE",id:"military-leave-of-absence",level:2},{value:"PERSONAL NON-FMLA LEAVE OF ABSENCE",id:"personal-non-fmla-leave-of-absence",level:2},{value:"EDUCATIONAL LEAVE OF ABSENCE",id:"educational-leave-of-absence",level:2},{value:"PUBLIC SERVICE LEAVE OF ABSENCE",id:"public-service-leave-of-absence",level:2},{value:"CONTINUATION OF BENEFITS",id:"continuation-of-benefits",level:2}];function c(e){const o={h1:"h1",h2:"h2",h3:"h3",h4:"h4",header:"header",li:"li",ol:"ol",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(o.header,{children:(0,i.jsx)(o.h1,{id:"iv-leave-of-absence-policies",children:"IV. LEAVE OF ABSENCE POLICIES"})}),"\n",(0,i.jsx)(o.h2,{id:"family-and-medical-leave",children:"FAMILY AND MEDICAL LEAVE"}),"\n",(0,i.jsx)(o.p,{children:"Pressure Profile Systems, Inc. grants family and medical leaves of absence to \u201celigible  employees\u201d for the following:"}),"\n",(0,i.jsxs)(o.ol,{children:["\n",(0,i.jsx)(o.li,{children:"the birth of an employee\u2019s child or to care for the newborn child;"}),"\n",(0,i.jsx)(o.li,{children:"the placement of a child with the employee for adoption or state-approved foster  care;"}),"\n",(0,i.jsx)(o.li,{children:"the care of an employee\u2019s spouse, child, or parent (\u201cfamily member\u201d) who has a  serious health condition; or"}),"\n",(0,i.jsx)(o.li,{children:"the employee\u2019s serious health condition which prevents the employee from  performing any one essential function of the employee\u2019s position."}),"\n"]}),"\n",(0,i.jsx)(o.p,{children:"A serious health condition is an illness, injury, impairment, or, physical or mental  condition that involves either inpatient care or continuing treatment by a health care  provider."}),"\n",(0,i.jsx)(o.h3,{id:"eligible-employee",children:"Eligible Employee"}),"\n",(0,i.jsx)(o.p,{children:"An active full-time or part-time employee is eligible for family and medical leave under  The Family and Medical Leave Act of 1993 (\u201cthe Act\u201d) provided that on the date the  employee requests leave:"}),"\n",(0,i.jsxs)(o.ol,{children:["\n",(0,i.jsx)(o.li,{children:"He has been employed by Pressure Profile Systems, Inc. for at least 12 months; and"}),"\n",(0,i.jsx)(o.li,{children:"He has worked 1,250 hours during the 12-month period immediately preceding the  commencement of leave."}),"\n"]}),"\n",(0,i.jsx)(o.h4,{id:"length-of-leave",children:"Length of Leave"}),"\n",(0,i.jsx)(o.p,{children:"An eligible employee is entitled to a total of 12-work weeks of unpaid leave within a 12- month period. The amount of leave available to an employee will be calculated by  looking backward at the amount of leave taken within the 12-month period immediately  preceding the first date of leave. Leave taken for the care of a newborn child or  placement for adoption or foster care must be taken as an uninterrupted, continuous leave  of absence and must be taken within 12 months of the birth or placement of the child. If  both a husband and wife are employed by Pressure Profile Systems, Inc., and are eligible  for leave, except for leave due to the employee\u2019s serious health condition, the two may  take a combined total of 12-weeks. Intermittent leave or a reduced schedule may be  approved for the employee\u2019s serious health condition or a family member\u2019s serious health  condition where medically necessary and where the need for such leave is best  accommodated through such scheduling. An employee requesting intermittent  leave/reduced schedule may be transferred temporarily to an available alternative position  with equivalent pay and benefits, or to a part-time position if such a position better  accommodates the need for intermittent leave/reduced schedule."}),"\n",(0,i.jsx)(o.h3,{id:"substitution-of-paid-leave",children:"Substitution of Paid Leave"}),"\n",(0,i.jsx)(o.p,{children:"An employee taking family and medical leave due to the employee\u2019s serious health  condition must substitute all accrued sick leave, unused paid vacation, personal leave,  paid time off and short-term salary continuation, if applicable, before continuing leave on  an unpaid basis. An employee taking leave for reasons other than an employee\u2019s own  serious health condition must exhaust all accrued unused paid vacation, personal leave  and paid time off before continuing leave on an unpaid basis. Any family and medical  leave, whether paid, unpaid, or a combination thereof, will be counted toward the 12- week leave entitlement."}),"\n",(0,i.jsx)(o.h4,{id:"employee-notification-requirements",children:"Employee Notification Requirements"}),"\n",(0,i.jsx)(o.p,{children:"If an employee expects to take family and medical leave, the employee must notify the  Pressure Profile Systems, Inc. Benefits Department of the intention to take leave at least  30 days in advance of the expected leave. Following proper notification, the employee  must complete a Leave of Absence Request form and provide any required medical  certification.\nIf the need for leave is not foreseeable, the employee must provide notification of leave to  the Pressure Profile Systems, Inc. Benefits Department as soon as is practicable under the  circumstances. An employee\u2019s failure to provide 30 days advance notification for  foreseeable leave may result in a delay of leave."}),"\n",(0,i.jsx)(o.h4,{id:"medical-certification",children:"Medical Certification"}),"\n",(0,i.jsx)(o.p,{children:"An employee who takes leave for the employee\u2019s serious health condition or to care for a  family member with a serious health condition must submit to the Pressure Profile  Systems, Inc. Benefits Department written medical certification of the need for such leave  from the applicable health care provider. Failure to provide the certification in a timely  manner may result in a delay of leave. Pressure Profile Systems, Inc. may request a  second or third medical opinion at Pressure Profile Systems, Inc.\u2019s expense for  verification of an employee\u2019s serious health condition. The opinion of the third health  care provider, who is approved jointly by Pressure Profile Systems, Inc. and the  employee, shall be final and binding on Pressure Profile Systems, Inc. and the employee.  In addition, while the employee is on leave, Pressure Profile Systems, Inc. may require  the employee to provide periodic recertification of the employee\u2019s medical condition (not  to exceed once every 30 days) and Pressure Profile Systems, Inc. may inquire as to the  employee\u2019s intentions to return to work."}),"\n",(0,i.jsx)(o.p,{children:"An employee on uninterrupted, continuous leave due to the employee\u2019s own serious  health condition will be required to provide a job-related medical certification of fitness  before the employee is allowed to return to work. Failure to provide this certification  may result in the delay or denial of job restoration."}),"\n",(0,i.jsx)(o.h4,{id:"benefits-continuation",children:"Benefits Continuation"}),"\n",(0,i.jsx)(o.p,{children:"The same health care benefits coverage provided to an employee on the day prior to  taking family and medical leave will be maintained during the 12-week leave, provided  the employee continues to pay any required contribution for benefits. Employees who are  on leave are responsible for making his periodic payment of the required contribution to  Pressure Profile Systems, Inc. at the following address:"}),"\n",(0,i.jsx)(o.p,{children:"Pressure Profile Systems, Inc. Companies, Inc.\n5757 Century Blvd. Suite 600\nLos Angeles, CA 90045\nAttn: Health Care Claims Specialist"}),"\n",(0,i.jsx)(o.p,{children:"Upon completion of the 12-week leave, or if an employee fails to maintain his  contribution for benefits, or fails to return to work at the end of leave, a loss of coverage  will occur, and continuation of health care coverage would be offered through COBRA.  An employee who does not return from leave may be required, under certain  circumstances provided by the Act, to reimburse Pressure Profile Systems, Inc. for any  employee contributions paid by Pressure Profile Systems, Inc. while the employee was on  unpaid leave."}),"\n",(0,i.jsx)(o.p,{children:"While on leave, an employee must continue to pay the employee\u2019s premiums or loan  payments for any applicable benefits which would otherwise be automatically deducted  from the employee\u2019s wages (e.g., Medical & Dental Insurance). Contact your Pressure  Profile Systems, Inc. Payroll Specialist for details regarding employee premiums and/or  loan payments.\nThe period of time an employee is on family and medical leave will be treated as  continued service for purposes of vesting and eligibility to participate under any available  pension or retirement plan. Absences due to leave will not be counted as time worked for  the purpose of seniority or computing vacation, sick leave or personal days."}),"\n",(0,i.jsx)(o.h4,{id:"job-restoration",children:"Job Restoration"}),"\n",(0,i.jsx)(o.p,{children:"An employee will be returned to the same or an equivalent position when the employee  returns from family and medical leave, with no loss of benefits accrued prior to leave. An  employee who does not return to work at the end of an authorized leave is subject to  termination of employment. In the event an employee\u2019s position with Pressure Profile  Systems, Inc. is affected by a decision or event not related to the employee\u2019s leave of  absence, e.g., job elimination due to a reduction in force, the employee will be affected to  the same extent as if he/she was not on leave."}),"\n",(0,i.jsx)(o.p,{children:"Certain \u201ckey employees\u201d as defined under The Family and Medical Leave Act of 1993  may not be eligible to be restored to the same or an equivalent position after leave if  doing so would cause substantial and grievous economic injury to the operations of the  assigned company. Pressure Profile Systems, Inc. will notify such employees of their  \u201ckey employee\u201d status and the conditions under which job restoration will be denied, if  applicable."}),"\n",(0,i.jsx)(o.h4,{id:"workers-compensation-and-family-and-medical-leave",children:"Workers' Compensation and Family and Medical Leave"}),"\n",(0,i.jsx)(o.p,{children:'With some exceptions, an absence related to a workers\' compensation injury is not  counted against an employee\'s family and medical leave entitlement. If an employee who  was injured on the job and as a result who suffered a "serious health condition" declines the offer of a medically-approved "light duty" position, the employee should notify  Pressure Profile Systems, Inc. Human Resource Department that he chooses to exercise  his family and medical leave rights, if he is so eligible. If the employee accepts the "light  duty" position in lieu of any family and medical leave or returns to work within 12 weeks  after the date of the injury, the employee will retain his right to be restored to the same or  an equivalent position until 12 weeks have passed unless a decision or event not related to  the employee\'s leave of absence occurs which results in the termination of the employee  or the elimination of the job position.'}),"\n",(0,i.jsx)(o.h4,{id:"questions-about-family-and-medical-leave",children:"Questions About Family and Medical Leave"}),"\n",(0,i.jsx)(o.p,{children:"If you have any questions about your rights or responsibilities under this policy, contact  the Pressure Profile Systems, Inc. Benefits Department.\nPressure Profile Systems, Inc. will comply with all applicable federal, state and local laws  in administering this policy."}),"\n",(0,i.jsx)(o.h2,{id:"pregnancy-disability-leave",children:"PREGNANCY DISABILITY LEAVE"}),"\n",(0,i.jsx)(o.p,{children:"Pregnancy, childbirth or related medical conditions will be treated like any other  disability, and an employee on leave will be eligible for temporary disability benefits in  the same amount and degree as any other employee on leave."}),"\n",(0,i.jsx)(o.p,{children:"All female employees should advise Human Resources of their intent to take pregnancy  disability leave as soon as possible. The individual should make an appointment with the  designated manager so that the following may be explained:"}),"\n",(0,i.jsxs)(o.ol,{children:["\n",(0,i.jsx)(o.li,{children:"If the need for the leave or transfer is foreseeable because of the pregnancy,  employees must provide at least (30) days\u2019 advance notice before the pregnancy  disability leave or transfer is to begin. Employees must consult with their manager  regarding the scheduling of any planned medical treatment or supervision so as to  minimize disruption to the operations of the company. Any such scheduling is  subject to the approval of the health care provider of the employee. If (30) days\u2019  advance notice is not possible, notice must be given as soon as practicable.\nEmployees who need to take pregnancy disability must provide at least verbal notice  sufficient to notify the company that the employee needs to take a pregnancy  disability leave and/or transfer. The verbal notice should include the anticipated  timing and duration of the leave or transfer."}),"\n",(0,i.jsx)(o.li,{children:"If requested by the employee and recommended by the employee\u2019s health care  provider, the employee\u2019s work assignment may be changed as required to protect the  health and safety of the employee and her child."}),"\n",(0,i.jsx)(o.li,{children:"Requests for temporary transfers of job duties will be reasonably accommodated if the  job and security rights of others are not breached."}),"\n",(0,i.jsx)(o.li,{children:"Temporary transfers due to health considerations will be granted where possible."}),"\n",(0,i.jsxs)(o.li,{children:["Pregnancy leave usually will begin when ordered by the employee\u2019s health care  provider. If requested, the employee must provide the Company with a certification  from a health care provider. The certification indicating disability should contain:","\n",(0,i.jsxs)(o.ul,{children:["\n",(0,i.jsx)(o.li,{children:"The date on which the employee became disabled due to pregnancy;"}),"\n",(0,i.jsx)(o.li,{children:"The probable duration of the period or periods of disability, and"}),"\n",(0,i.jsx)(o.li,{children:"Statement that, due to the disability, the employee is unable to perform one or more  of the essential functions of her position without undue risk to herself, the  successful completion of her pregnancy, or to other persons."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(o.li,{children:"A return from leave will be allowed only when the employee provides a release to the  company from her health care provider."}),"\n",(0,i.jsx)(o.li,{children:"An employee will be required to use all accrued sick time, if any is available, during a  pregnancy disability leave. An employee will be allowed to use accrued vacation or  personal time (if otherwise eligible to take the time) during a pregnancy disability  leave."}),"\n",(0,i.jsx)(o.li,{children:"Duration of the leave will be determined by the advice of the employee\u2019s health care  provider, but disabled employees may take up to four months. Part-time employees  are entitled to leave on a pro rata basis. The four months of leave includes any period  of time for actual disability caused by the employee\u2019s pregnancy, childbirth or related  medical condition. This includes leave for severe morning sickness and for prenatal  care."}),"\n"]}),"\n",(0,i.jsx)(o.p,{children:"Leave does not need to be taken in one continuous period of time and may be taken  intermittently, as needed."}),"\n",(0,i.jsx)(o.p,{children:"Under most circumstances, upon submission of a medical certification that an employee  is able to return to work from a pregnancy disability leave, an employee will be reinstated  to her same position held at the time the leave began or to an equivalent position with the  same pay rate/salary, if available. An employee returning from a pregnancy disability  leave has no greater right to reinstatement than if the employee had been continuously  employed rather than on leave. For example, if the employee on pregnancy disability  would have been laid off had she not gone on leave, or if the employee\u2019s position has  been eliminated due to a reduction in force, and there are no equivalent or comparable  positions available, then the employee would not be entitled to reinstatement."}),"\n",(0,i.jsx)(o.p,{children:"While on leave, group health insurance will be continued as is provided for in the  Continuation of Benefits policy."}),"\n",(0,i.jsx)(o.h2,{id:"military-leave-of-absence",children:"MILITARY LEAVE OF ABSENCE"}),"\n",(0,i.jsx)(o.p,{children:"A leave of absence without pay for military or reserve duty is granted to full-time regular  and part-time regular employees. If an employee is called to active military duty or the  reserve or National Guard training, or if an employee volunteers for the same, the  employee should submit copies of military orders to the on-site supervisor as soon as  possible. The employee will be granted a military leave of absence without pay for the  period of military service, in accordance with applicable federal and state laws. If the  employee is a reservist or a member of the National Guard, the employee is granted time  off without pay for required military training. However, the employee may use any  earned but unused vacation available. Eligibility for reinstatement after military duty or  training is completed is determined in accordance with applicable federal and state laws."}),"\n",(0,i.jsx)(o.h2,{id:"personal-non-fmla-leave-of-absence",children:"PERSONAL NON-FMLA LEAVE OF ABSENCE"}),"\n",(0,i.jsx)(o.p,{children:"Employees may be granted a leave of absence to attend to personal matters in situations  in which the Company determines that an extended period of time away from the job will  be in the best interests of the employee and the Company."}),"\n",(0,i.jsx)(o.p,{children:"Requests for a leave of absence or any extension of a leave should be submitted in writing  to the employee\u2019s supervisor thirty days prior to commencement of the leave period, or as  soon as is practicable. The supervisor will forward the request to appropriate  management recommending approval or denial. The final decision concerning the  request will be made by the Manager. All employees on approved leave are expected to  report any change of status in their need for leave or their intention to return to work to  their supervisor."}),"\n",(0,i.jsx)(o.p,{children:"Employees on personal leave will be required to use all accrued personal and vacation  days while on leave before going unpaid. The Company will continue health insurance  and other benefits to employees on leave for no longer than 12 weeks from the beginning  date of leave so long as the employee continues to pay any employee portion of the  contribution. Benefits that accrue according to length of service, such as paid vacation,  holiday, personal and sick days, do not accrue during periods of leave."}),"\n",(0,i.jsx)(o.p,{children:"Employees returning from a personal leave due to an illness or injury must provide a job related release indicating their ability to perform the functions of their job. Any  restrictions must be noted on the release."}),"\n",(0,i.jsx)(o.p,{children:"Employees on an authorized personal leave of absence may not perform work for any  other employer that is considered by the Company to be a conflict of interest.\nAn employee returning from a personal leave of absence may not be returned to the same  job position that they held before taking leave. If an employee fails to return to work at  the conclusion of an approved leave of absence, including any extension of the leave  time, the employee will be considered to have voluntarily terminated employment with  the Company."}),"\n",(0,i.jsx)(o.h2,{id:"educational-leave-of-absence",children:"EDUCATIONAL LEAVE OF ABSENCE"}),"\n",(0,i.jsx)(o.p,{children:"Employees who want to continue their education in preparation for added responsibilities  with the Company may be granted an educational leave of absence.\nRequests for a leave of absence or any extension of a leave should be submitted in writing  to the employee\u2019s supervisor thirty days prior to commencement of the leave period, or as  soon as is practicable. The supervisor will forward the request to appropriate  management recommending approval or denial. The final decision concerning the  request will be made by the Manager. All employees on approved leave are expected to  report any change of status in their need for leave or their intention to return to work to  their supervisor."}),"\n",(0,i.jsx)(o.p,{children:"Employees on educational leave will be required to use all accrued personal and vacation  days while on leave before going unpaid. The Company will continue health insurance  and other benefits to employees on leave for no longer than 12 weeks from the beginning  date of leave so long as the employee continues to pay any employee portion of the  contribution. Benefits that accrue according to length of service, such as paid vacation,  holiday, personal and sick days, do not accrue during periods of leave."}),"\n",(0,i.jsx)(o.p,{children:"Employees on an authorized educational leave of absence may not perform work for any  other employer that is considered by the Company to be a conflict of interest."}),"\n",(0,i.jsx)(o.p,{children:"An employee returning from an educational leave of absence may not be returned to the  same job position that they held before taking leave. If an employee fails to return to  work at the conclusion of an approved leave of absence, including any extension of the  leave time, the employee will be considered to have voluntarily terminated employment  with the Company."}),"\n",(0,i.jsx)(o.h2,{id:"public-service-leave-of-absence",children:"PUBLIC SERVICE LEAVE OF ABSENCE"}),"\n",(0,i.jsx)(o.p,{children:"Employees who want to accept temporary employment in federal, state, or local  government or with an organization devoted to community service may be granted a leave  of absence."}),"\n",(0,i.jsx)(o.p,{children:"Requests for a leave of absence or any extension of a leave should be submitted in writing  to the employee\u2019s supervisor thirty days prior to commencement of the leave period, or as  soon as is practicable. The supervisor will forward the request to appropriate  management recommending approval or denial. The final decision concerning the  request will be made by the Manager. All employees on approved leave are expected to  report any change of status in their need for leave or their intention to return to work to  their supervisor."}),"\n",(0,i.jsx)(o.p,{children:"Employees on public service leave will be required to use all accrued personal and  vacation days while on leave before going unpaid. The Company will continue health  insurance and other benefits to employees on leave for no longer than 12 weeks from the  beginning date of leave so long as the employee continues to pay any employee portion of  the contribution. Benefits that accrue according to length of service, such as paid  vacation, holiday, personal and sick days, do not accrue during periods of leave."}),"\n",(0,i.jsx)(o.p,{children:"Employees on an authorized public service leave of absence may not perform work for  any other employer that is considered by the Company to be a conflict of interest.\nAn employee returning from a public service leave of absence may not be returned to the  same job position that they held before taking leave. If an employee fails to return to  work at the conclusion of an approved leave of absence, including any extension of the  leave time, the employee will be considered to have voluntarily terminated employment  with the Company."}),"\n",(0,i.jsx)(o.h2,{id:"continuation-of-benefits",children:"CONTINUATION OF BENEFITS"}),"\n",(0,i.jsx)(o.p,{children:"It is the policy of Pressure Profile Systems, Inc. to provide the following health care  benefits to employees who are away from work."}),"\n",(0,i.jsx)(o.p,{children:"All active full-time employees covered by the Pressure Profile Systems, Inc. Benefit Plan  will be eligible to continue medical coverage for 12 weeks following the beginning of a  leave for:"}),"\n",(0,i.jsxs)(o.ul,{children:["\n",(0,i.jsx)(o.li,{children:"an authorized, paid or unpaid leave of absence; or"}),"\n",(0,i.jsx)(o.li,{children:"a temporary lay-off due to lack of work."}),"\n"]}),"\n",(0,i.jsx)(o.p,{children:"An employee who is away from work for one of the above stated reasons must pay his  share of employee coverage, including dependent coverage, if any, to maintain health care  coverage during the time away from work. Upon the expiration of 12 weeks, or if an  employee fails to pay his employee contribution for benefits within 30 days from the  established due date communicated to the employee and no applicable state or federal law  provides otherwise, the employee\u2019s health care coverage, including dependent coverage,  will be terminated. Continuation of health care coverage will be offered through  COBRA."})]})}function h(e={}){const{wrapper:o}={...(0,a.R)(),...e.components};return o?(0,i.jsx)(o,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,o,t){t.d(o,{R:()=>r,x:()=>l});var n=t(6540);const i={},a=n.createContext(i);function r(e){const o=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function l(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(a.Provider,{value:o},e.children)}}}]);